const updateForwardedSystemMessages = `-- name: UpdateForwardedSystemMessages :many
UPDATE messages SET payload = $2
WHERE forwarded_from = $1 AND kind = 'system' AND deleted_at IS NULL
RETURNING id, room_id, author_id, content, reply_to_id, nonce, created_at, edited_at, deleted_at, pinned_at, pinned_by, embeds_hidden, kind, payload, sticker_id, forwarded_from, forward_author_id, forward_sent_at, inline_keyboard, keyboard_revision
`

type UpdateForwardedSystemMessagesParams struct {
	ForwardedFrom *uuid.UUID
	Payload       []byte
}

// The live forwarded copies of a recording card follow it (ADR-0033 §4).
func (q *Queries) UpdateForwardedSystemMessages(ctx context.Context, arg UpdateForwardedSystemMessagesParams) ([]Message, error) {
	rows, err := q.db.Query(ctx, updateForwardedSystemMessages, arg.ForwardedFrom, arg.Payload)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Message{}
	for rows.Next() {
		var i Message
		if err := rows.Scan(
			&i.ID,
			&i.RoomID,
			&i.AuthorID,
			&i.Content,
			&i.ReplyToID,
			&i.Nonce,
			&i.CreatedAt,
			&i.EditedAt,
			&i.DeletedAt,
			&i.PinnedAt,
			&i.PinnedBy,
			&i.EmbedsHidden,
			&i.Kind,
			&i.Payload,
			&i.StickerID,
			&i.ForwardedFrom,
			&i.ForwardAuthorID,
			&i.ForwardSentAt,
			&i.InlineKeyboard,
			&i.KeyboardRevision,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

